import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Object3D();
  const timelines = [];
  const initialPosition = { x: -2.5, y: -0.2, z: 0 };
  let mesh = null;

  // Load the GLB mesh and clone it for this instance
  const glb = ctx.glbLoader.load(config.meshUrl);
  if (glb && glb.scene) {
    mesh = glb.scene.clone();
    container.add(mesh);
  }

  // Apply scene placement
  container.position.set(initialPosition.x, initialPosition.y, initialPosition.z);

  // Setup interaction handlers
  const handlers = {
    onHover: () => {
      timelines.forEach(tl => tl.kill());
      timelines.length = 0;

      const timeline = gsap.to(container.position, {
        y: initialPosition.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      timelines.push(timeline);
    },

    onHoverOut: () => {
      timelines.forEach(tl => tl.kill());
      timelines.length = 0;

      const timeline = gsap.to(container.position, {
        y: initialPosition.y,
        duration: 0.7,
        ease: 'power3.out',
      });
      timelines.push(timeline);
    },

    onClick: () => {
      container.dispatchEvent({
        type: 'hub-home.select',
        detail: config,
      });
    },
  };

  container.userData.handlers = handlers;

  container.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    if (mesh) {
      mesh.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(mat => mat.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  return container;
}
